"""Speed guard for the Fourier solver: results stay unchanged.

Reference values come from the present solver before the speed change
(task T-0025). The test solves 3 wings at 2 angles with ``solve`` and
with ``solve_sweep`` and compares every total, every spanwise array
and the Fourier coefficients against the stored values.
"""

from __future__ import annotations

import numpy as np
import pytest

import ventorum as vt
from ventorum.solvers.fourier import FourierSolver

N_TERMS = 80
REL_TOL = 1e-12
ABS_TOL = 1e-14


def _wing_rect():
    """Return the rectangular reference wing."""
    af = vt.LinearAirfoil(a0=2 * np.pi, alpha_L0=0.0, Cd0=0.004, Cm0=-0.05)
    return vt.LiftingSurface(
        name="rect",
        semi_span=5.0,
        sections=[
            vt.WingSection(y_frac=0.0, chord=1.25, airfoil=af),
            vt.WingSection(y_frac=1.0, chord=1.25, airfoil=af),
        ],
    )


def _wing_tapered():
    """Return the tapered reference wing with a straight quarter-chord line."""
    af = vt.LinearAirfoil(a0=2 * np.pi, alpha_L0=0.0, Cd0=0.004, Cm0=-0.05)
    af_tip = vt.LinearAirfoil(a0=2 * np.pi, alpha_L0=np.radians(-1.0), Cd0=0.005, Cm0=-0.04)
    return vt.LiftingSurface(
        name="tapered",
        semi_span=5.0,
        sections=[
            vt.WingSection(y_frac=0.0, chord=2.0, x_le=0.0, airfoil=af),
            vt.WingSection(y_frac=0.5, chord=1.2, x_le=0.2, airfoil=af),
            vt.WingSection(y_frac=1.0, chord=0.8, x_le=0.3, airfoil=af_tip),
        ],
    )


def _wing_elliptic():
    """Return the elliptic-chord reference wing with washout."""
    af = vt.LinearAirfoil(a0=2 * np.pi, alpha_L0=0.0, Cd0=0.004, Cm0=-0.05)
    c_root = 1.6
    sections = []
    for k in range(9):
        eta = k / 8
        chord = 1.6 * np.sqrt(max(1e-9, 1 - eta ** 2))
        sections.append(
            vt.WingSection(
                y_frac=float(eta),
                chord=float(chord),
                x_le=float(0.25 * (c_root - chord)),
                twist=float(np.radians(-2 * eta)),
                airfoil=af,
            )
        )
    return vt.LiftingSurface(name="elliptic", semi_span=5.0, sections=sections)


def _wings():
    """Return the reference wings by name."""
    return {"rect": _wing_rect(), "tapered": _wing_tapered(), "elliptic": _wing_elliptic()}


def _check_close(actual, expected, label):
    """Assert that *actual* matches *expected* within the task tolerance."""
    if expected is None:
        assert actual is None, f"{label}: expected None, got {actual!r}"
        return
    if isinstance(expected, float) and np.isnan(expected):
        assert isinstance(actual, float) and np.isnan(actual), f"{label}: expected nan, got {actual!r}"
        return
    a = np.asarray(actual, dtype=float)
    e = np.asarray(expected, dtype=float)
    assert a.shape == e.shape, f"{label}: shape {a.shape} != {e.shape}"
    if e.size == 1 and not np.isnan(float(e.flat[0])):
        denom = max(abs(float(e.flat[0])), 1e-300)
        err = np.max(np.abs(a - e)) / denom if denom > 0 else np.max(np.abs(a - e))
        assert err <= REL_TOL or np.max(np.abs(a - e)) <= ABS_TOL, f"{label}: rel err {err:.3g}"
    else:
        scale = np.maximum(np.abs(e), 1e-14)
        with np.errstate(invalid="ignore"):
            ok = (np.abs(a - e) <= ABS_TOL) | (np.abs(a - e) / scale <= REL_TOL)
        ok = np.where(np.isnan(e), np.isnan(a), ok)
        assert bool(np.all(ok)), f"{label}: max rel err {np.nanmax(np.abs(a - e) / scale):.3g}"


def _check_result(result, ref, label):
    """Assert that one solver result matches its reference entry."""
    totals = result.totals
    for key in ("CL", "CDi", "CDp", "CD_total", "e", "AR", "Cm"):
        _check_close(getattr(totals, key), ref[key], f"{label} totals.{key}")
    _check_close(np.asarray(result.fourier_coefficients, dtype=float), np.asarray(ref["coeffs"], dtype=float),
                 f"{label} coeffs")
    span = result.spanwise[0]
    for key in ("y", "gamma", "Cl", "Cd_i", "Cd_profile", "alpha_eff", "alpha_i", "local_lift", "chord",
                "Cm_section"):
        _check_close(None if getattr(span, key) is None else np.asarray(getattr(span, key), dtype=float),
                     None if ref[f"sp_{key}"] is None else np.asarray(ref[f"sp_{key}"], dtype=float),
                     f"{label} spanwise.{key}")


def test_fourier_results_unchanged():
    """Compare solve and solve_sweep against the stored reference values."""
    solver = FourierSolver()
    wings = _wings()
    settings = vt.SolverSettings(solver_type="fourier", n_panels=N_TERMS)
    for (name, alpha_deg), ref in REF.items():
        condition = vt.FlightCondition(V_inf=25.0, alpha=np.radians(alpha_deg))
        result = solver.solve(wings[name], condition, settings)
        _check_result(result, ref, f"{name} alpha={alpha_deg} solve")
    for name, wing in wings.items():
        alphas = np.radians(np.array([0.0, 5.0]))
        base = vt.FlightCondition(V_inf=25.0, alpha=0.0)
        for result, alpha_deg in zip(solver.solve_sweep(wing, base, settings, alphas), [0.0, 5.0]):
            _check_result(result, REF[(name, alpha_deg)], f"{name} alpha={alpha_deg} sweep")


